mapper.select:
select * from eval_case_working_copy

  and status=#{status}
  and owner_user_id=#{ownerUserId}

order by updated_at desc, id desc limit #{limit} offset #{offset}

mapper.update:
update eval_case_working_copy
set candidate_id=#{workingCopy.candidateId}, status=#{workingCopy.status}, definition_json=#{workingCopy.definitionJson},
    evaluation_target=#{workingCopy.evaluationTarget}, target_migration_status=#{workingCopy.targetMigrationStatus},
    revision=#{workingCopy.revision}, updated_at=#{workingCopy.updatedAt}
where id=#{workingCopy.id} and revision=#{expectedRevision}
